int get_interface_settings(struct fst_card_info *card, struct fst_port_info *port, struct ifreq *ifr) {
    int err = 0;
    struct sync_info sync;

    if (!card || !port || !ifr)
        return -EFAULT;

    /* Determine line type based on hardware interface of the port */
    switch (port->hw_if_type) {
        case IF_TYPE_T1:
            ifr->ifr_type = IFT_T1;
            break;
        case IF_TYPE_E1:
            ifr->ifr_type = IFT_E1;
            break;
        case IF_TYPE_E3:
            ifr->ifr_type = IFT_E3;
            break;
        default:
            return -EFAULT;
    }

    /* Check requested size */
    if (ifr->ifr_size < sizeof(struct sync_info))
        return -ENOMEM;

    /* Initialize sync structure with clock rate and type */
    sync.clock_rate = card->clock_rate;
    sync.clock_type = card->clock_type;

    /* Copy sync data to user space */
    if (copy_to_user(ifr->ifr_data, &sync, sizeof(sync)))
        err = -EFAULT;

    /* Update the size in the ifr structure */
    ifr->ifr_size = sizeof(struct sync_info);

    return err;
}

